-- Seed VIG-009 R4 (#241, épica #239): Achango como primer caso completo del
-- Banco de Potencialidades del nodo iglesia (Bloque 9, dominio #160, patrón
-- seed-oportunidades-vig008): estado detected (registro comunitario sujeto a
-- revisión), evidencia obligatoria con evidence_type canónico, actores SIN
-- nombre y consent_confirmed=false (ADR-027: ningún actor se nombra sin
-- consentimiento formal, VIG-009 R3), created_by_hash 'seed-vig-009' = sello de
-- origen, no un ciudadano. Candados epistémicos del diseño #241: la estimación
-- ~50M ARS es testimonio del cuidador, NO presupuesto oficial; agua, energía y
-- conectividad del paraje = unknown sin relevamiento; sin plazos inventados.
-- Idempotencia: ON CONFLICT (hash) DO NOTHING.

INSERT INTO oportunidades (id, tipo, titulo, descripcion, estado, nodo_key, subnodo_key, evidencia, actores, tags, created_by_hash, hash, created_at, updated_at)
VALUES
  (gen_random_uuid()::text, 'physical_asset', 'Conjunto MHN de Achango (capilla, caserío, cementerio y corrales)', 'Conjunto declarado Monumento Histórico Nacional por Ley 24.790 (1997), con ficha patrimonial viva (VIG-004). Estado crítico documentado por prensa 2026 — testimonio periodístico, no diagnóstico técnico oficial (R15, verificación 2026-10-17, #241).', 'detected', 'iglesia', NULL, '{"evidence_type":"institutional_document","descripcion":"Ley Nacional 24.790 (1997) declaratoria MHN del conjunto de Achango; estado crítico según testimonio periodístico 2026 (verificación 2026-10-17, diseño #241)."}'::jsonb, '[{"role":"beneficiary","consent_confirmed":false}]'::jsonb, '["achango","mhn","patrimonio","ley_24790"]'::jsonb, 'seed-vig-009', 'seed-oportunidad-vig009-mhn', '2026-10-20T13:00:00Z', '2026-10-20T13:00:00Z'),
  (gen_random_uuid()::text, 'cultural_asset', 'Nudo textil de Achango: alfombras centenarias, telar de suelo y tintes nativos', 'Alfombras de nudo de más de 350 años tapizando el piso de tierra, telar de suelo y tintes nativos (algarrobo, jarilla, ruibarbo, cochinilla, minerales). Proyecto 2022 de ofrenda de jergones para la festividad de la Virgen del Carmen (16 de julio) con Mercado Artesanal Tradicional y Municipio de Iglesia. Nombres de maestras teleras NO se registran sin consentimiento (ADR-027, Ley 25.326).', 'detected', 'iglesia', NULL, '{"evidence_type":"news_source","descripcion":"Prensa 2022-2026: proyecto de ofrenda de jergones, telar de suelo y piezas textiles del nudo de Achango (verificación 2026-10-17, diseño #241)."}'::jsonb, '[{"role":"provider","consent_confirmed":false},{"role":"supporter","consent_confirmed":false}]'::jsonb, '["achango","textil","tintes_nativos","patrimonio_vivo"]'::jsonb, 'seed-vig-009', 'seed-oportunidad-vig009-nudo-achango', '2026-10-20T13:00:00Z', '2026-10-20T13:00:00Z'),
  (gen_random_uuid()::text, 'institutional_asset', 'Custodia familiar con relevo generacional del conjunto MHN de Achango', 'Familia guardiana con relevo generacional y un único habitante permanente que riega y limpia la capilla a diario según prensa (hecho demográfico publicable con fuente). En la plataforma la custodia es un ROL, jamás un nombre propio (ADR-027, Ley 25.326); el instrumento de consentimiento granular queda disponible (VIG-009 R3).', 'detected', 'iglesia', NULL, '{"evidence_type":"news_source","descripcion":"Testimonio periodístico 2026 sobre la custodia familiar con relevo generacional y el único habitante permanente del paraje (verificación 2026-10-17, diseño #241)."}'::jsonb, '[{"role":"provider","consent_confirmed":false}]'::jsonb, '["achango","custodia","patrimonio","adr_027"]'::jsonb, 'seed-vig-009', 'seed-oportunidad-vig009-custodia-familiar', '2026-10-20T13:00:00Z', '2026-10-20T13:00:00Z'),
  (gen_random_uuid()::text, 'detected_demand', 'Restauración urgente del conjunto MHN de Achango (demanda testimonial, sin presupuesto oficial)', 'Cornisas arruinadas, techos y maderos cediendo y riesgo de colapso latente según testimonio periodístico 2026; estimación de restauración de unos 50 millones de pesos SEGÚN EL CUIDADOR — testimonio, NO presupuesto oficial. Más de 15 años de notas a Nación, Provincia y Municipio sin fondos (Diario 13 San Juan). Agua, energía y conectividad del paraje: unknown sin relevamiento, NO se inventan (R15).', 'detected', 'iglesia', NULL, '{"evidence_type":"news_source","descripcion":"Testimonio periodístico 2026 (modoviajeok 01-2026, Diario 13 San Juan): estado crítico, estimación del cuidador ~50M ARS y notas sin respuesta (verificación 2026-10-17, diseño #241)."}'::jsonb, '[{"role":"beneficiary","consent_confirmed":false}]'::jsonb, '["achango","restauracion","mhn","notas_sin_respuesta"]'::jsonb, 'seed-vig-009', 'seed-oportunidad-vig009-demanda-restauracion', '2026-10-20T13:00:00Z', '2026-10-20T13:00:00Z'),
  (gen_random_uuid()::text, 'market_gap', 'Turismo patrimonial sin prestador formal en el corredor Pismanta-Las Flores', 'Candidata a la ruta del Pasaporte Sanmartiniano y locación de la película Martina Chapanay; demanda textil con oficio en riesgo de extinción (registrado 04-2026) y pedidos corporativos de ponchos desde la gran minería hacia los telares de Tudcum. Sin prestador formal de turismo patrimonial en el corredor — brecha registrada, demanda NO verificada con relevamiento propio (R15).', 'detected', 'iglesia', NULL, '{"evidence_type":"news_source","descripcion":"Prensa 2024-2026: Pasaporte Sanmartiniano, oficio textil en riesgo de extinción y demanda minera de ponchos (verificación 2026-10-17, diseño #241)."}'::jsonb, '[{"role":"provider","consent_confirmed":false}]'::jsonb, '["achango","turismo","textil","pasaporte_sanmartiniano"]'::jsonb, 'seed-vig-009', 'seed-oportunidad-vig009-turismo-patrimonial', '2026-10-20T13:00:00Z', '2026-10-20T13:00:00Z'),
  (gen_random_uuid()::text, 'partnership_opportunity', 'Mapa de actores para el rescate de Achango: CNM, Provincia, Municipio, RSE minera, cooperativas y universidad', 'Vías formales verificadas, todas en trámite hasta gestión formal: CNM/Secretaría de Cultura (superintendencia MHN, Ley 12.665; más de 15 años de notas sin fondos según prensa); PEDL Iglesia 2018 con la restauración de Achango como Proyecto (Informe de Avance 2024, sin ejecución acreditada); Municipio de Iglesia co-gestor del proyecto de tejido 2022; RSE minera con precedentes verificados (riego por goteo 2015, programa Mujeres en Red); FECOAGRO y cooperativas del distrito a 3,7 km del paraje (ver VIG-008); UNSJ/CONICET.', 'detected', 'iglesia', NULL, '{"evidence_type":"institutional_document","descripcion":"Informe de Avance PEDL 2024 y prensa provincial: mapa de actores con vías verificables, todas en trámite (verificación 2026-10-17, diseño #241)."}'::jsonb, '[{"role":"partner","consent_confirmed":false},{"role":"supporter","consent_confirmed":false}]'::jsonb, '["achango","cnm","pedl","rse_minera","cooperativas"]'::jsonb, 'seed-vig-009', 'seed-oportunidad-vig009-alianzas', '2026-10-20T13:00:00Z', '2026-10-20T13:00:00Z'),
  (gen_random_uuid()::text, 'investment_opportunity', 'Inversión en restauración del conjunto MHN (candado epistémico: estimación testimonial)', 'Oportunidad de inversión SOLO con candado epistémico: la única cifra disponible es la estimación testimonial del cuidador (unos 50 millones de pesos, modoviajeok 01-2026) — NO es presupuesto oficial; todo monto formal exige proyecto técnico y presupuesto acreditado. La plataforma no recauda ni canaliza fondos (manifiesto de cero recaudación, R15).', 'detected', 'iglesia', NULL, '{"evidence_type":"news_source","descripcion":"Estimación testimonial del cuidador ~50M ARS (modoviajeok 01-2026), no presupuesto oficial (verificación 2026-10-17, diseño #241)."}'::jsonb, '[{"role":"validator","consent_confirmed":false}]'::jsonb, '["achango","restauracion","inversion","candado_epistemico"]'::jsonb, 'seed-vig-009', 'seed-oportunidad-vig009-inversion-restauracion', '2026-10-20T13:00:00Z', '2026-10-20T13:00:00Z'),
  (gen_random_uuid()::text, 'policy_opportunity', 'Ventanas de política pública: PEDL, Pasaporte Sanmartiniano y Leyes 6.801/7.911', 'La restauración de las capillas de Achango y Santo Domingo figura como Proyecto en el PEDL Iglesia (Informe de Avance 2024, sin ejecución acreditada); candidatura a la ruta del Pasaporte Sanmartiniano; marco provincial de patrimonio ya verificado (Leyes 6.801 y 7.911). Ventana registrada como oportunidad — sin plazos inventados (R15).', 'detected', 'iglesia', NULL, '{"evidence_type":"institutional_document","descripcion":"PEDL Iglesia 2018 (Informe de Avance 2024) y marco provincial de patrimonio (Leyes 6.801/7.911) verificado (verificación 2026-10-17, diseño #241)."}'::jsonb, '[{"role":"partner","consent_confirmed":false}]'::jsonb, '["achango","pedl","pasaporte_sanmartiniano","leyes_patrimoniales"]'::jsonb, 'seed-vig-009', 'seed-oportunidad-vig009-politica-publica', '2026-10-20T13:00:00Z', '2026-10-20T13:00:00Z')
ON CONFLICT (hash) DO NOTHING;

-- Sellos oportunidad.propuesta (patrón seed-fuentes-vig: events_raw única
-- fuente de verdad; hash = hash de la oportunidad → idempotencia; payload
-- source 'seed-vig-009' distingue el origen; sin PII).
INSERT INTO events_raw (id, type, payload, hash, occurred_at, ingested_at)
SELECT gen_random_uuid()::text, 'oportunidad.propuesta',
       jsonb_build_object('oportunidad_id', o.id, 'tipo', o.tipo, 'nodo_key', o.nodo_key, 'subnodo_key', o.subnodo_key, 'estado', o.estado, 'created_by_hash', o.created_by_hash, 'source', 'seed-vig-009'),
       o.hash, o.created_at, o.created_at
FROM oportunidades o
WHERE o.created_by_hash = 'seed-vig-009'
ON CONFLICT (hash) DO NOTHING;
